import DeviceInfo from 'react-native-device-info';

/**
 * 1.2.3 still receives this plan from the API. 1.2.2 must hide it locally.
 * Match the catalog name and the translated labels used by the current screens.
 */
const HIDDEN_APP_VERSION = '1.2.2';

const SINGLE_TELECONSULT_LABELS = new Set([
  'single teleconsult',
  'teleconsults x1',
  '单次线上视频问诊',
  '單次線上視訊診症',
]);

const NAME_FIELDS = [
  'name',
  'displayName',
  'policyName',
  'planName',
] as const;

export const readInstalledAppVersion = (): string => DeviceInfo.getVersion();

export const isSingleTeleconsultHiddenVersion = (
  version: string = readInstalledAppVersion(),
): boolean => version === HIDDEN_APP_VERSION;

const pushLabel = (labels: string[], value: unknown): void => {
  if (typeof value !== 'string') {
    return;
  }
  const trimmed = value.trim();
  if (!trimmed) {
    return;
  }
  labels.push(trimmed);
  const withoutSuffix = trimmed.split(' (')[0]?.trim();
  if (withoutSuffix && withoutSuffix !== trimmed) {
    labels.push(withoutSuffix);
  }
};

const collectPlanLabels = (
  value: unknown,
  labels: string[],
  depth: number,
): void => {
  if (depth > 2 || value === null || typeof value !== 'object') {
    return;
  }
  const record = value as Record<string, unknown>;
  NAME_FIELDS.forEach(field => {
    pushLabel(labels, record[field]);
  });
  collectPlanLabels(record.plan, labels, depth + 1);
  collectPlanLabels(record.product, labels, depth + 1);
};

const normalizePlanLabel = (value: string): string => value.trim().toLowerCase();

export const isSingleTeleconsultPlan = (plan: unknown): boolean => {
  const labels: string[] = [];
  collectPlanLabels(plan, labels, 0);
  return labels.some(label =>
    SINGLE_TELECONSULT_LABELS.has(normalizePlanLabel(label)),
  );
};

export const shouldHideSingleTeleconsultPlan = (
  plan: unknown,
  version: string = readInstalledAppVersion(),
): boolean =>
  isSingleTeleconsultHiddenVersion(version) && isSingleTeleconsultPlan(plan);

export const withoutSingleTeleconsultPlans = <T>(
  plans: readonly T[],
  version: string = readInstalledAppVersion(),
): T[] => {
  if (!isSingleTeleconsultHiddenVersion(version)) {
    return plans as T[];
  }
  return plans.filter(plan => !isSingleTeleconsultPlan(plan));
};

import {
  isSingleTeleconsultPlan,
  shouldHideSingleTeleconsultPlan,
  withoutSingleTeleconsultPlans,
} from '../src/helper/single-teleconsult-plan';

jest.mock('react-native-device-info', () => ({
  __esModule: true,
  default: {
    getVersion: () => '1.2.3',
  },
}));

const travelPlan = {
  id: 'travel-single',
  name: 'Travel Plan - Single',
  displayName: 'Travel Plan - Single',
  type: 'travel',
};

const singleTeleconsultProduct = {
  id: 'single-teleconsult',
  name: 'Teleconsults x1',
  displayName: 'Single Teleconsult',
  type: 'premium',
};

describe('Single Teleconsult visibility on 1.2.2', () => {
  test('recognizes the plan by catalog name, display name, and translated labels', () => {
    expect(isSingleTeleconsultPlan(singleTeleconsultProduct)).toBe(true);
    expect(isSingleTeleconsultPlan({name: 'Teleconsults x1'})).toBe(true);
    expect(isSingleTeleconsultPlan({displayName: '单次线上视频问诊'})).toBe(true);
    expect(isSingleTeleconsultPlan({displayName: '單次線上視訊診症'})).toBe(true);
    expect(
      isSingleTeleconsultPlan({
        plan: {name: 'Single Teleconsult (HK)'},
      }),
    ).toBe(true);
    expect(
      isSingleTeleconsultPlan({
        product: {displayName: 'Single Teleconsult'},
      }),
    ).toBe(true);
    expect(isSingleTeleconsultPlan(travelPlan)).toBe(false);
    expect(
      isSingleTeleconsultPlan({
        name: 'HomeDoc Care Single Plan',
        displayName: 'HomeDoc Care Single Plan',
      }),
    ).toBe(false);
    expect(isSingleTeleconsultPlan({type: 'premium', name: 'Premium Plan 365'})).toBe(
      false,
    );
  });

  test('hides the plan only when the installed version is exactly 1.2.2', () => {
    expect(shouldHideSingleTeleconsultPlan(singleTeleconsultProduct, '1.2.2')).toBe(
      true,
    );
    expect(shouldHideSingleTeleconsultPlan(travelPlan, '1.2.2')).toBe(false);
    expect(shouldHideSingleTeleconsultPlan(singleTeleconsultProduct, '1.2.1')).toBe(
      false,
    );
    expect(shouldHideSingleTeleconsultPlan(singleTeleconsultProduct, '1.2.3')).toBe(
      false,
    );
    expect(shouldHideSingleTeleconsultPlan(singleTeleconsultProduct, '1.2.20')).toBe(
      false,
    );
  });

  test('filters list entries on 1.2.2 and keeps the original list on other versions', () => {
    const plans = [travelPlan, singleTeleconsultProduct];

    expect(withoutSingleTeleconsultPlans(plans, '1.2.2')).toEqual([travelPlan]);
    expect(withoutSingleTeleconsultPlans(plans, '1.2.3')).toBe(plans);
  });
});

