export const MINIMUM_SUPPORTED_VERSION = '1.2.2';

const IOS_APP_STORE_IDS: Record<string, string> = {
  'com.healshealthcare.healspass': '6544800416',
  'com.healshealthcare.healspass.dev': '6740129703',
};

const parseVersionParts = (version: string): number[] =>
  String(version ?? '')
    .split('.')
    .map(part => {
      const parsed = parseInt(part, 10);
      return Number.isFinite(parsed) ? parsed : 0;
    });

export const compareVersions = (left: string, right: string): number => {
  const leftParts = parseVersionParts(left);
  const rightParts = parseVersionParts(right);
  const length = Math.max(leftParts.length, rightParts.length);

  for (let index = 0; index < length; index += 1) {
    const leftPart = leftParts[index] ?? 0;
    const rightPart = rightParts[index] ?? 0;
    if (leftPart > rightPart) {
      return 1;
    }
    if (leftPart < rightPart) {
      return -1;
    }
  }

  return 0;
};

/** Matches the integer the minimum-version API already stores, such as 1.2.2 -> 122. */
export const toLegacyVersionCode = (version: string): number => {
  const parsed = parseInt(String(version ?? '').replace(/\./g, ''), 10);
  return Number.isFinite(parsed) ? parsed : 0;
};

export const isBelowMinimumSupportedVersion = (installedVersion: string): boolean =>
  compareVersions(installedVersion, MINIMUM_SUPPORTED_VERSION) < 0;

const isPositiveVersionCode = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value) && value > 0;

export const requiresStoreUpdate = (input: {
  installedVersion: string;
  platform: 'ios' | 'android';
  iosMinimumCode?: unknown;
  androidMinimumCode?: unknown;
}): boolean => {
  if (isBelowMinimumSupportedVersion(input.installedVersion)) {
    return true;
  }

  const minimumCode =
    input.platform === 'ios' ? input.iosMinimumCode : input.androidMinimumCode;
  if (!isPositiveVersionCode(minimumCode)) {
    return false;
  }

  return toLegacyVersionCode(input.installedVersion) < minimumCode;
};

export const resolveIosAppStoreId = (bundleId: string): string =>
  IOS_APP_STORE_IDS[bundleId] ??
  (bundleId.endsWith('.dev') ? '6740129703' : '6544800416');

export const getIosStoreUrl = (bundleId: string): string =>
  `itms-apps://apps.apple.com/app/id${resolveIosAppStoreId(bundleId)}`;

export const getIosStoreWebUrl = (bundleId: string): string =>
  `https://apps.apple.com/app/id${resolveIosAppStoreId(bundleId)}`;

export const getAndroidStoreUrl = (bundleId: string): string =>
  `market://details?id=${bundleId}`;

export const getAndroidStoreWebUrl = (bundleId: string): string =>
  `https://play.google.com/store/apps/details?id=${bundleId}`;

import React, {useEffect} from 'react';
import {
  Linking,
  Platform,
  StyleSheet,
  TouchableOpacity,
  View,
} from 'react-native';
import DeviceInfo from 'react-native-device-info';
import {SafeAreaView} from 'react-native-safe-area-context';
import AppText from '@components/app-text/app-text';
import {
  getAndroidStoreUrl,
  getAndroidStoreWebUrl,
  getIosStoreUrl,
  getIosStoreWebUrl,
} from '@helper/app-update-policy';

const openStore = async (): Promise<void> => {
  const bundleId = DeviceInfo.getBundleId();
  const primaryUrl =
    Platform.OS === 'ios' ? getIosStoreUrl(bundleId) : getAndroidStoreUrl(bundleId);
  const fallbackUrl =
    Platform.OS === 'ios'
      ? getIosStoreWebUrl(bundleId)
      : getAndroidStoreWebUrl(bundleId);

  try {
    await Linking.openURL(primaryUrl);
  } catch (error) {
    console.log(`exception encountered ${error}`);
    try {
      await Linking.openURL(fallbackUrl);
    } catch (fallbackError) {
      console.log(`exception encountered ${fallbackError}`);
    }
  }
};

const ForceUpdateScreen: React.FC = () => {
  useEffect(() => {
    void openStore();
  }, []);

  return (
    <SafeAreaView style={styles.page}>
      <View style={styles.content}>
        <AppText style={styles.title}>{$i18n.t('force_update_title')}</AppText>
        <AppText style={styles.message}>{$i18n.t('force_update_message')}</AppText>
        <TouchableOpacity style={styles.button} onPress={() => void openStore()}>
          <AppText style={styles.buttonText}>{$i18n.t('force_update_button')}</AppText>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  page: {
    flex: 1,
    backgroundColor: '#FFFFFF',
  },
  content: {
    flex: 1,
    justifyContent: 'center',
    paddingHorizontal: 24,
  },
  title: {
    fontSize: 22,
    lineHeight: 28,
    fontWeight: '700',
    color: '#0F1617',
    textAlign: 'center',
  },
  message: {
    marginTop: 12,
    fontSize: 16,
    lineHeight: 24,
    color: '#4B6363',
    textAlign: 'center',
  },
  button: {
    marginTop: 28,
    height: 48,
    borderRadius: 24,
    backgroundColor: '#00AC86',
    alignItems: 'center',
    justifyContent: 'center',
  },
  buttonText: {
    color: '#FFFFFF',
    fontSize: 16,
    fontWeight: '700',
  },
});

export default ForceUpdateScreen;

import {
  compareVersions,
  getAndroidStoreUrl,
  getIosStoreUrl,
  requiresStoreUpdate,
  toLegacyVersionCode,
} from '../src/helper/app-update-policy';

describe('store update policy from 1.2.2', () => {
  test('compares marketing versions by numeric parts', () => {
    expect(compareVersions('1.2.1', '1.2.2')).toBe(-1);
    expect(compareVersions('1.2.2', '1.2.2')).toBe(0);
    expect(compareVersions('1.2.3', '1.2.2')).toBe(1);
    expect(compareVersions('1.2.10', '1.2.2')).toBe(1);
    expect(compareVersions('1.10.0', '1.2.2')).toBe(1);
  });

  test('blocks installs below 1.2.2 and keeps 1.2.2 usable', () => {
    expect(
      requiresStoreUpdate({
        installedVersion: '1.2.1',
        platform: 'android',
        androidMinimumCode: 100,
      }),
    ).toBe(true);
    expect(
      requiresStoreUpdate({
        installedVersion: '1.2.2',
        platform: 'ios',
        iosMinimumCode: 106,
      }),
    ).toBe(false);
    expect(
      requiresStoreUpdate({
        installedVersion: '1.2.3',
        platform: 'android',
        androidMinimumCode: 100,
      }),
    ).toBe(false);
  });

  test('still blocks when the server minimum is newer than the installed legacy code', () => {
    expect(toLegacyVersionCode('1.2.2')).toBe(122);
    expect(
      requiresStoreUpdate({
        installedVersion: '1.2.2',
        platform: 'ios',
        iosMinimumCode: 123,
      }),
    ).toBe(true);
    expect(
      requiresStoreUpdate({
        installedVersion: '1.2.2',
        platform: 'android',
      }),
    ).toBe(false);
  });

  test('opens the store for the current Heals bundle', () => {
    expect(getIosStoreUrl('com.healshealthcare.healspass')).toBe(
      'itms-apps://apps.apple.com/app/id6544800416',
    );
    expect(getIosStoreUrl('com.healshealthcare.healspass.dev')).toBe(
      'itms-apps://apps.apple.com/app/id6740129703',
    );
    expect(getAndroidStoreUrl('com.healshealthcare.healspass.dev')).toBe(
      'market://details?id=com.healshealthcare.healspass.dev',
    );
  });
});

