export const readDoctorPage = (response: unknown): unknown[] | null => {
  if (!response || typeof response !== 'object') {
    return null;
  }
  const data = (response as {data?: unknown}).data;
  return Array.isArray(data) ? data : null;
};

import {readDoctorPage} from '../src/screens/doctor-list-screen/doctor-list-paging';

describe('doctor list paging payload', () => {
  test('reads a doctor array', () => {
    expect(readDoctorPage({success: true, data: [{id: '1'}]})).toEqual([{id: '1'}]);
  });

  test('returns null when the failed response has no data array', () => {
    expect(readDoctorPage({success: false})).toBeNull();
    expect(readDoctorPage({data: undefined})).toBeNull();
    expect(readDoctorPage(undefined)).toBeNull();
  });

  test('treats an empty page as finished', () => {
    expect(readDoctorPage({success: true, data: []})).toEqual([]);
  });
});

